import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const g=JSON.parse('{"title":"Chat, messages and pings","description":"","frontmatter":{"pageId":"players/chat-pings","contentRevision":2},"headers":[],"relativePath":"en/players/chat-pings.md","filePath":"en/players/chat-pings.md"}'),n={name:"en/players/chat-pings.md"};function r(o,e,c,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="chat-messages-and-pings" tabindex="-1">Chat, messages and pings <a class="header-anchor" href="#chat-messages-and-pings" aria-label="Permalink to &quot;Chat, messages and pings&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Public chat is visible to server participants. A direct message targets a specific player. Alliance chat is available to current alliance members; check the channel before sending.</p><p>Text such as <code>[[tile:123]]</code> creates a location card. A ping points to a world tile or coordinates on the active map; a visit/live counterpart may be the default recipient. Use pings for coordination, not secret data.</p><p>Blocking a player prevents messages, gifts, trades and pings between you. Notification settings and letter-triggered pauses are separate controls.</p><h3 id="send-a-ping" tabindex="-1">Send a ping <a class="header-anchor" href="#send-a-ping" aria-label="Permalink to &quot;Send a ping&quot;">​</a></h3><p>Point at the location and press <strong>G</strong>; change the binding in <strong>Options → Keyboard → Rimlink</strong>. On the world map this marks a tile, on a colony map a cell. A visit/live session can use the current counterpart as recipient. Typing in a text field never sends a ping. The recipient sees a temporary marker (8 seconds); if absent, check recipient, blocks and the 12-per-minute limit. For a persistent chat location card send <code>[[tile:123]]</code> with the intended tile number.</p><h2 id="channels" tabindex="-1">Public, direct and alliance channels: who receives a message? <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Public, direct and alliance channels: who receives a message? {#channels}&quot;">​</a></h2><p>Check channel and recipient before sending. Public chat reaches server participants and, if configured, the public Discord bridge. Direct messages target one player. Alliance chat is for current members; visible history begins at your join time and is not bridged to Discord.</p><p>A [[tile:123]] card stays in the message and opens a location; G creates an eight-second marker, not a persistent note. On a colony map it marks a cell; on the planet it marks a tile. Never put passwords, tokens or private data in public chat.</p><p>If a message/ping fails, check recipient, blocks in either direction, mute and rate limits. Blocking also prevents new gifts/trades and cancels existing mutual trades, but is not a raid or market ban.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Public chat may be relayed to Discord. Blocking does not disable raids, markets or visits. Alliance chat and direct messages are not part of the public Discord bridge.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./community">Profiles, friends and alliances</a></li><li><a href="./live">Live: the active map</a></li><li><a href="./../admins/discord">Discord bot</a></li></ul>',16)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
